var sv = SubViewport.new()
sv.size = Vector2i(256, 256)
sv.own_world_3d = true
sv.transparent_bg = false
sv.render_target_update_mode = SubViewport.UPDATE_ALWAYS
var base = EditorInterface.get_base_control()
base.add_child(sv)
var env = Environment.new()
env.background_mode = Environment.BG_COLOR
env.background_color = Color(0.1,0.1,0.1)
var we = WorldEnvironment.new()
we.environment = env
sv.add_child(we)
var box = MeshInstance3D.new()
box.mesh = BoxMesh.new()
box.position = Vector3(0,0,0)
sv.add_child(box)
var light = DirectionalLight3D.new()
light.rotation_degrees = Vector3(-45,-30,0)
sv.add_child(light)
var cam = Camera3D.new()
cam.position = Vector3(2.5,2.0,2.5)
cam.look_at_from_position(Vector3(2.5,2.0,2.5), Vector3.ZERO, Vector3.UP)
sv.add_child(cam)
sv.set_update_mode(SubViewport.UPDATE_ALWAYS)
# force several render frames to settle
for i in range(6):
	RenderingServer.force_draw(false)
var img = sv.get_texture().get_image()
var total = img.get_width() * img.get_height()
var bg = Color(0.1,0.1,0.1)
var nonbg = 0
for y in range(0, img.get_height(), 2):
	for x in range(0, img.get_width(), 2):
		var c = img.get_pixel(x,y)
		if abs(c.r-bg.r) > 0.04 or abs(c.g-bg.g) > 0.04 or abs(c.b-bg.b) > 0.04:
			nonbg += 1
img.save_png("user://ivan_retry_isolated_box.png")
_mcp_print("sampled_total: " + str((img.get_width()/2)*(img.get_height()/2)))
_mcp_print("nonbg_pixels: " + str(nonbg))
_mcp_print("img_size: " + str(img.get_size()))
sv.queue_free()
